const $ = (s, el=document) => el.querySelector(s);
const $$ = (s, el=document) => [...el.querySelectorAll(s)];
const money = n => `GHS ${Number(n||0).toLocaleString('en-GH',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
const shortMoney = n => `GHS ${Number(n||0).toLocaleString('en-GH',{maximumFractionDigits:0})}`;
const iso = d => new Date(d).toISOString().slice(0,10);
const today = iso(new Date());
const monthKey = today.slice(0,7);
const monthName = new Date().toLocaleDateString('en-GH',{month:'long',year:'numeric'});
const uid = p => `${p}-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;

const seed = {
  transactions:[
    {id:'t1',type:'income',amount:3200,date:`${monthKey}-03`,category:'Client payment',description:'Kente House brand work',person:'Joey',status:'received',createdBy:'Joey'},
    {id:'t2',type:'income',amount:2650,date:`${monthKey}-12`,category:'Salary',description:'Monthly salary',person:'Ama',status:'received',createdBy:'Ama'},
    {id:'t3',type:'expense',amount:480,date:`${monthKey}-04`,category:'Food',description:'Groceries',person:'Both',paidBy:'Ama',createdBy:'Ama'},
    {id:'t4',type:'expense',amount:180,date:`${monthKey}-07`,category:'Transport',description:'Fuel',person:'Joey',paidBy:'Joey',createdBy:'Joey'},
    {id:'t5',type:'expense',amount:300,date:`${monthKey}-10`,category:'Internet',description:'Home fibre',person:'Both',paidBy:'Joey',createdBy:'Joey',recurring:true},
    {id:'t6',type:'income',amount:2000,date:iso(new Date(Date.now()+8*864e5)),category:'Client payment',description:'Noka final payment',person:'Joey',status:'expected',createdBy:'Joey'},
    {id:'t7',type:'expense',amount:120,date:`${monthKey}-14`,category:'Subscriptions',description:'Design software',person:'Joey',paidBy:'Joey',createdBy:'Joey',recurring:true}
  ],
  debts:[{id:'d1',person:'Joey',direction:'borrowed',amount:2000,date:`${monthKey}-02`,due:iso(new Date(Date.now()+14*864e5)),description:'Camera repair',createdBy:'Ama'}],
  debtPayments:[{id:'dp1',debtId:'d1',amount:750,date:`${monthKey}-18`,person:'Joey'}],
  goals:[{id:'g1',name:'Emergency fund',target:10000,current:3500,date:'2027-03-31'},{id:'g2',name:'New camera',target:8500,current:2100,date:'2027-01-15'},{id:'g3',name:'December travel',target:4000,current:2900,date:'2026-12-10'}],
  customers:[{id:'c1',name:'Noka Studio',company:'Noka Studio',email:'hello@noka.example',phone:'024 000 1240'},{id:'c2',name:'Kente House',company:'Kente House',email:'accounts@kente.example',phone:'055 120 4021'}],
  projects:[{id:'p1',customerId:'c1',name:'Brand refresh',status:'Awaiting Payment',amount:4000,paid:2000,due:iso(new Date(Date.now()+8*864e5))},{id:'p2',customerId:'c2',name:'Social campaign',status:'Active',amount:3200,paid:3200,due:iso(new Date(Date.now()+20*864e5))}],
  work:[{id:'w1',customerId:'c1',projectId:'p1',date:`${monthKey}-05`,description:'Identity concepts',amount:800},{id:'w2',customerId:'c1',projectId:'p1',date:`${monthKey}-12`,description:'Brand guidelines',amount:1200}],
  invoices:[{id:'i1',number:'INV-2026-0001',customerId:'c1',projectId:'p1',issue:`${monthKey}-15`,due:iso(new Date(Date.now()+8*864e5)),status:'Sent',items:[{description:'Brand identity deposit',qty:1,rate:2000}],discount:0,tax:0}],
  invoicePayments:[],
  plans:[{month:monthKey,income:8000,expenses:4400,savings:1500,debt:800}],
  activities:[{id:'a1',text:'Ama recorded GHS 750.00 repayment from Joey.',date:`${monthKey}-18`},{id:'a2',text:'Joey added GHS 120.00 for design software.',date:`${monthKey}-14`}]
};
const emptyData={transactions:[],debts:[],debtPayments:[],goals:[],customers:[],projects:[],work:[],invoices:[],invoicePayments:[],plans:[],activities:[],sharedExpenses:[],recurring:[],notifications:[],deletedCustomerIds:[]};
let data = JSON.parse(localStorage.getItem('ours-data-v2')||'null') || structuredClone(emptyData);
let state = {user:localStorage.getItem('ours-user')||'Joey',view:'home',tab:'all'};
const save=()=>{localStorage.setItem('ours-data-v2',JSON.stringify(data));queueCloudSync()};
const navs=[['home','⌂','Home'],['money','↕','Money'],['plan','◔','Plan'],['business','▣','Business'],['more','•••','More']];

function totals(){
  const tx=data.transactions.filter(t=>t.date.startsWith(monthKey));
  const income=tx.filter(t=>t.type==='income'&&t.status!=='expected').reduce((s,t)=>s+t.amount,0);
  const expense=tx.filter(t=>t.type==='expense').reduce((s,t)=>s+t.amount,0);
  const allReceivedIncome=data.transactions.filter(t=>t.type==='income'&&t.status!=='expected').reduce((s,t)=>s+(Number(t.amount)||0),0);
  const allExpenses=data.transactions.filter(t=>t.type==='expense').reduce((s,t)=>s+(Number(t.amount)||0),0);
  const saved=data.goals.reduce((s,g)=>s+g.current,0);
  const debt=data.debts.reduce((s,d)=>s+Math.max(0,d.amount-data.debtPayments.filter(p=>p.debtId===d.id).reduce((a,p)=>a+p.amount,0)),0);
  const receivable=data.invoices.reduce((s,i)=>s+invoiceBalance(i),0);
  return {income,expense,saved,debt,receivable,remaining:allReceivedIncome-allExpenses};
}
function invoiceSubtotal(invoice){return invoice.items.reduce((sum,item)=>sum+(Number(item.qty)||0)*(Number(item.rate)||0),0)}
function invoiceDiscount(invoice){const subtotal=invoiceSubtotal(invoice),value=Number(invoice.discountValue??invoice.discount??0)||0;return invoice.discountType==='percent'?Math.min(subtotal,subtotal*value/100):Math.min(subtotal,value)}
function invoiceTotal(invoice){return Math.max(0,invoiceSubtotal(invoice)-invoiceDiscount(invoice)+(Number(invoice.tax)||0))}
function invoicePaid(i){return data.invoicePayments.filter(p=>p.invoiceId===i.id).reduce((s,p)=>s+p.amount,0)}
function invoiceBalance(i){return Math.max(0,invoiceTotal(i)-invoicePaid(i))}
function customer(id){return data.customers.find(c=>c.id===id)||{name:'Unknown customer'} }
function activity(text){data.activities.unshift({id:uid('a'),text,date:today});}

function init(){
  renderNav();
  $$('#login-form .person').forEach(b=>b.onclick=()=>{$$('.person').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.user=b.dataset.person});
  $('#login-form').onsubmit=e=>{e.preventDefault();if($('#pin').value!=='2026')return toast('That access code is incorrect');localStorage.setItem('ours-user',state.user);$('#auth').classList.add('hidden');$('#app').classList.remove('hidden');render()};
  $('#fab').onclick=()=>openQuick(); $('#overlay').onclick=closeSheet; $('#search-btn').onclick=openSearch;
  $('#sync-btn').onclick=manualSync;
  $('#profile-btn').onclick=()=>openSheet('Your workspace',`<div class="section"><p><b>${state.user}</b><br><span style="color:var(--muted)">Shared securely with ${state.user==='Joey'?'Ama':'Joey'}</span></p></div><button class="secondary" id="signout">Lock workspace</button>`); 
  if(localStorage.getItem('ours-user')){$('#auth').classList.add('hidden');$('#app').classList.remove('hidden');render()}
}
function renderNav(){
  const html=navs.map(n=>`<button class="nav-item ${state.view===n[0]?'active':''}" data-nav="${n[0]}"><i>${n[1]}</i>${n[2]}</button>`).join('');
  $('#bottom-nav').innerHTML=html;$('#desktop-nav').innerHTML=html;
  $$('[data-nav]').forEach(b=>b.onclick=()=>{state.view=b.dataset.nav;if(state.view==='money')state.tab='all';renderNav();render()});
}
function pageHead(title,sub='',action=''){return `<div class="page-head"><div><span class="eyebrow">${sub}</span><h1>${title}</h1></div>${action}</div>`}
function render(){
  $('#profile-btn').textContent=state.user[0];$('#side-name').textContent=state.user;
  const views={home:homeView,money:moneyView,plan:planView,business:businessView,more:moreView};
  $('#view').innerHTML=views[state.view]();bindView();window.scrollTo({top:0,behavior:'smooth'});
}
function homeView(){const t=totals();const hour=new Date().getHours();const greet=hour<12?'Good morning':hour<18?'Good afternoon':'Good evening';
  return `${pageHead(`${greet},<br>${state.user}.`,monthName.toUpperCase(),'<button class="text-button" data-action="review">Review →</button>')}
  <div class="dashboard-grid"><div><section class="hero"><span class="eyebrow">AVAILABLE BALANCE</span><div class="hero-number">${shortMoney(t.remaining)}</div><div class="hero-sub">Carries forward from previous months</div><div class="metric-row"><div class="metric"><b>${shortMoney(t.income)}</b><span>Money in this month</span></div><div class="metric"><b>${shortMoney(t.expense)}</b><span>Money out this month</span></div><div class="metric"><b>${shortMoney(data.goals.reduce((s,g)=>s+g.current,0))}</b><span>Total saved</span></div></div></section>
  <section class="section"><div class="section-title"><h2>Income & spending</h2><span>Last 6 months</span></div>${chart()}<div class="chart-legend"><span><i class="dot"></i>Income</span><span><i class="dot gray"></i>Spending</span></div></section></div>
  <div><section class="section"><div class="section-title"><h2>Coming up</h2><button class="text-button" data-nav="plan">View plan</button></div><ul class="clean-list">${upcomingRows()}</ul></section>
  <section class="section"><div class="section-title"><h2>Financial snapshot</h2></div><div class="snapshot"><div class="snap"><b>${shortMoney(t.debt)}</b><span>Debt outstanding</span></div><div class="snap"><b>${shortMoney(t.receivable)}</b><span>Customers owe</span></div></div></section></div></div>`}
function chart(){
  const months=Array.from({length:6},(_,index)=>{const date=new Date();date.setDate(1);date.setMonth(date.getMonth()-(5-index));return {key:`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}`,label:date.toLocaleDateString('en-GH',{month:'short'}),income:0,expense:0}});
  data.transactions.forEach(transaction=>{const month=months.find(item=>transaction.date?.startsWith(item.key));if(!month)return;if(transaction.type==='income'&&transaction.status!=='expected')month.income+=Number(transaction.amount)||0;if(transaction.type==='expense')month.expense+=Number(transaction.amount)||0});
  const max=Math.max(0,...months.flatMap(item=>[item.income,item.expense]));
  if(!max)return `<div class="chart-empty"><span>↕</span><b>No activity yet</b><small>Your income and spending will appear here.</small></div>`;
  return `<div class="chart">${months.map(item=>`<div class="bar-group" title="${item.label}: ${money(item.income)} in, ${money(item.expense)} out"><i class="bar" style="height:${item.income/max*100}%"></i><i class="bar out" style="height:${item.expense/max*100}%"></i><label>${item.label}</label></div>`).join('')}</div>`
}
function upcomingRows(){const rows=[...data.transactions.filter(t=>t.status==='expected'||t.recurring).map(t=>({name:t.description,sub:t.status==='expected'?'Expected income':'Recurring',date:t.date,amount:t.amount,type:t.type})),...data.invoices.filter(i=>invoiceBalance(i)>0).map(i=>({name:customer(i.customerId).name,sub:'Invoice due',date:i.due,amount:invoiceBalance(i),type:'income'}))].sort((a,b)=>a.date.localeCompare(b.date)).slice(0,4);return rows.map(r=>row(r.name,`${r.sub} · ${prettyDate(r.date)}`,money(r.amount),r.type==='income'?'amount-in':'amount-out')).join('')}
function row(name,sub,amount,klass='',icon=''){return `<li class="list-row"><span class="row-icon">${icon||name[0]}</span><span class="row-main"><b>${name}</b><span>${sub}</span></span><span class="row-side"><b class="${klass}">${amount}</b></span></li>`}
function prettyDate(d){return new Date(`${d}T12:00`).toLocaleDateString('en-GH',{month:'short',day:'numeric'})}

function moneyView(){let list=''; if(state.tab==='debts')list=debtList();else {let tx=data.transactions.filter(t=>state.tab==='all'||t.type===state.tab).sort((a,b)=>b.date.localeCompare(a.date));list=tx.map(t=>row(t.description,`${t.category} · ${t.person} · ${prettyDate(t.date)}`,`${t.type==='expense'?'−':'+'}${money(t.amount)}`,t.type==='expense'?'amount-out':'amount-in',t.type==='expense'?'↗':'↙')).join('')}
return `${pageHead('Money','INCOME, SPENDING & DEBT','<button class="text-button" data-action="add-expense">Add new</button>')}<div class="segmented"><button data-tab="all" class="${state.tab==='all'?'active':''}">All</button><button data-tab="income" class="${state.tab==='income'?'active':''}">Income</button><button data-tab="expense" class="${state.tab==='expense'?'active':''}">Expenses</button><button data-tab="debts" class="${state.tab==='debts'?'active':''}">Debts</button></div><ul class="clean-list">${list||'<div class="empty"><b>Nothing here yet</b>Add your first record with the + button.</div>'}</ul>`}
function debtList(){return data.debts.map(d=>{const paid=data.debtPayments.filter(p=>p.debtId===d.id).reduce((s,p)=>s+p.amount,0),left=Math.max(0,d.amount-paid);return `<li class="goal-row"><div class="goal-top"><b>${d.person} ${d.direction}</b><span class="status ${left?'warn':''}">${left?'In progress':'Paid'}</span></div><div class="goal-values"><span>${money(paid)} paid of ${money(d.amount)}</span><b>${money(left)} left</b></div><div class="progress"><i style="width:${Math.min(100,paid/d.amount*100)}%"></i></div>${left?`<button class="text-button" data-repay="${d.id}">Record repayment</button>`:''}</li>`}).join('')}

function planView(){const plan=data.plans.find(p=>p.month===monthKey)||{income:0,expenses:0,savings:0,debt:0};const projected=plan.income-plan.expenses-plan.savings-plan.debt;return `${pageHead('Plan ahead','MONTHLY PLANNING')}<section class="hero"><span class="eyebrow">PROJECTED REMAINING</span><div class="hero-number">${shortMoney(projected)}</div><div class="hero-sub">after expenses, saving and debt payments</div></section><section class="section"><div class="section-title"><h2>Planned vs actual</h2><span>${monthName}</span></div>${compareRow('Income',plan.income,totals().income)}${compareRow('Expenses',plan.expenses,totals().expense)}${compareRow('Savings',plan.savings,0)}${compareRow('Debt repayment',plan.debt,data.debtPayments.filter(p=>p.date.startsWith(monthKey)).reduce((s,p)=>s+p.amount,0))}</section><section class="section"><div class="section-title"><h2>Savings goals</h2><button class="text-button" data-action="add-goal">New goal</button></div>${data.goals.map(goalRow).join('')}</section>`}
function compareRow(name,planned,actual){return `<div class="goal-row"><div class="goal-top"><b>${name}</b><span>${money(actual)} actual</span></div><div class="progress"><i style="width:${Math.min(100,actual/(planned||1)*100)}%"></i></div><div class="goal-values"><span>${Math.round(actual/(planned||1)*100)}%</span><span>${money(planned)} planned</span></div></div>`}
function goalRow(g){const pct=Math.min(100,Math.round(g.current/g.target*100));return `<div class="goal-row"><div class="goal-top"><b>${g.name}</b><span>${pct}%</span></div><div class="goal-values"><span>${money(g.current)} of ${money(g.target)}</span><span>${money(g.target-g.current)} left</span></div><div class="progress"><i style="width:${pct}%"></i></div><button class="text-button" data-contribute="${g.id}">Add contribution</button></div>`}

function businessView(){const outstanding=data.projects.reduce((s,p)=>s+Math.max(0,p.amount-p.paid),0);return `${pageHead('Business','FREELANCE WORKSPACE','<button class="text-button" data-action="add-customer">New customer</button>')}<section class="hero"><span class="eyebrow">OUTSTANDING</span><div class="hero-number">${shortMoney(outstanding)}</div><div class="metric-row"><div class="metric"><b>${data.customers.length}</b><span>Customers</span></div><div class="metric"><b>${data.projects.filter(p=>p.status==='Active').length}</b><span>Active work</span></div><div class="metric"><b>${data.invoices.filter(i=>invoiceBalance(i)>0).length}</b><span>Unpaid invoices</span></div></div></section><section class="section"><div class="section-title"><h2>Customers</h2><button class="text-button" data-action="add-project">Add project</button></div><ul class="clean-list">${data.customers.map(c=>{const ps=data.projects.filter(p=>p.customerId===c.id);const due=ps.reduce((s,p)=>s+Math.max(0,p.amount-p.paid),0);return row(c.name,`${ps.length} project${ps.length===1?'':'s'} · ${c.email}`,money(due),due?'amount-out':'','C')}).join('')}</ul></section><section class="section"><div class="section-title"><h2>Recent work</h2><button class="text-button" data-action="add-work">Log work</button></div><ul class="clean-list">${data.work.slice().reverse().map(w=>row(w.description,`${customer(w.customerId).name} · ${prettyDate(w.date)}`,money(w.amount),'amount-in','W')).join('')}</ul></section><section class="section"><div class="section-title"><h2>Invoices</h2><button class="text-button" data-action="add-invoice">Create invoice</button></div><ul class="clean-list">${data.invoices.map(i=>`<li class="list-row" data-invoice="${i.id}"><span class="row-icon">I</span><span class="row-main"><b>${i.number}</b><span>${customer(i.customerId).name} · Due ${prettyDate(i.due)}</span></span><span class="row-side"><b>${money(invoiceBalance(i))}</b><span class="status ${invoiceBalance(i)?'warn':''}">${invoiceBalance(i)?i.status:'Paid'}</span></span></li>`).join('')}</ul></section>`}

function moreView(){const t=totals();const food=data.transactions.filter(x=>x.type==='expense'&&x.category==='Food'&&x.date.startsWith(monthKey)).reduce((s,x)=>s+x.amount,0);const foodPct=t.expense?Math.round(food/t.expense*100):0;return `${pageHead('More','REPORTS & WORKSPACE')}<section><div class="section-title"><h2>Smart insights</h2><span>Based on your data</span></div><ul class="clean-list">${row('Spending pace',`You have spent ${money(t.expense)} this month.`,'','', '↗')}${row('Top category',`Food represents ${foodPct}% of monthly expenses.`,'','', '%')}${row('Receivables',`${money(t.receivable)} remains in unpaid invoices.`,'','', 'I')}</ul></section><section class="section"><div class="section-title"><h2>Monthly review</h2><button class="text-button" data-action="review">Open report</button></div><div class="snapshot"><div class="snap"><b>${shortMoney(t.income)}</b><span>Income</span></div><div class="snap"><b>${shortMoney(t.expense)}</b><span>Expenses</span></div><div class="snap"><b>${shortMoney(data.debtPayments.reduce((s,p)=>s+p.amount,0))}</b><span>Debt repaid</span></div><div class="snap"><b>${shortMoney(t.receivable)}</b><span>Outstanding</span></div></div></section><section class="section"><div class="section-title"><h2>Activity</h2></div><ul class="clean-list">${data.activities.map(a=>row(a.text,prettyDate(a.date),'','','•')).join('')}</ul></section><section class="section"><button class="secondary" id="export">Export my data</button> <button class="text-button" id="reset">Restore demo data</button></section>`}

function bindView(){
  $$('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;render()});
  $$('[data-action]').forEach(b=>b.onclick=()=>handleAction(b.dataset.action));
  $$('[data-repay]').forEach(b=>b.onclick=()=>openRepayment(b.dataset.repay));
  $$('[data-contribute]').forEach(b=>b.onclick=()=>openContribution(b.dataset.contribute));
  $$('[data-invoice]').forEach(b=>b.onclick=()=>openInvoice(b.dataset.invoice));
  $$('[data-customer]').forEach(b=>b.onclick=()=>openCustomerProfile(b.dataset.customer));
  $$('[data-transaction]').forEach(b=>b.onclick=()=>openTransactionDetail(b.dataset.transaction));
  $$('[data-project]').forEach(b=>b.onclick=()=>openProjectDetail(b.dataset.project));
  $('#export')?.addEventListener('click',()=>{const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='ours-finance-data.json';a.click();URL.revokeObjectURL(a.href)});
  $('#reset')?.addEventListener('click',()=>{data=structuredClone(seed);save();render();toast('Demo data restored')});
  $('#signout')?.addEventListener('click',()=>{localStorage.removeItem('ours-user');location.reload()});
}

function openSheet(title,body){$('#sheet').innerHTML=`<div class="sheet-head"><h2>${title}</h2><button class="close" aria-label="Close">×</button></div>${body}`;$('#overlay').classList.remove('hidden');$('#sheet').classList.remove('hidden');$('.close').onclick=closeSheet;bindView()}
function closeSheet(){$('#sheet').classList.add('hidden');$('#overlay').classList.add('hidden')}
function toast(s){const el=$('#toast');el.textContent=s;el.classList.remove('hidden');setTimeout(()=>el.classList.add('hidden'),2200)}
function openQuick(){openSheet('Quick add',`<div class="quick-grid">${[['add-income','↙','Income'],['add-expense','↗','Expense'],['add-debt','⇄','Debt'],['add-repayment','✓','Repayment'],['add-goal','◎','Savings'],['add-customer','C','Customer'],['add-project','P','Project'],['add-work','W','Work'],['add-invoice','I','Invoice']].map(x=>`<button class="quick-item" data-action="${x[0]}"><i>${x[1]}</i><span>${x[2]}</span></button>`).join('')}</div>`)}
function handleAction(a){const map={'add-income':()=>openTransaction('income'),'add-expense':()=>openTransaction('expense'),'add-debt':openDebt,'add-repayment':()=>data.debts.length?openRepayment(data.debts[0].id):toast('Add a debt first'),'add-goal':openGoal,'add-customer':openCustomer,'add-project':openProject,'add-work':openWork,'add-invoice':openNewInvoice,review:openReview};(map[a]||(()=>{}))()}
function options(arr,val=x=>x,label=x=>x){return arr.map(x=>`<option value="${val(x)}">${label(x)}</option>`).join('')}
function formWrap(fields,label='Save'){return `<form class="form">${fields}<div class="form-actions"><button type="button" class="secondary close-form">Cancel</button><button class="primary" type="submit">${label}</button></div></form>`}
function field(label,name,type='text',value='',extra='',full=''){return `<div class="field ${full}"><label>${label}</label><input name="${name}" type="${type}" value="${value}" ${extra}></div>`}
function selectField(label,name,opts,full=''){return `<div class="field ${full}"><label>${label}</label><select name="${name}">${opts}</select></div>`}
function setupForm(fn){$('.close-form').onclick=closeSheet;$('.form').onsubmit=e=>{e.preventDefault();fn(Object.fromEntries(new FormData(e.target)));save();closeSheet();render();toast('Saved successfully')}}

function openTransaction(type){const cats=type==='income'?['Client payment','Salary','Freelance design','Photography','Other']:['Food','Transport','Rent','Utilities','Internet','Phone','Shopping','Entertainment','Health','Family','Business','Subscriptions','Debt repayment','Savings','Other'];openSheet(`Add ${type}`,formWrap(`${field('Amount','amount','number','','step="0.01" min="0" required autofocus')}${selectField('For','person',options(['Joey','Ama','Both']))}${field(type==='income'?'Source':'Description','description','text','','required','full')}${selectField('Category','category',options(cats))}${field('Date','date','date',today,'required')}${type==='income'?selectField('Status','status',options(['received','expected'])):selectField('Paid by','paidBy',options(['Joey','Ama']))}${selectField('Frequency','frequency',options(['One-time','Recurring']))}`));setupForm(v=>{data.transactions.push({id:uid('t'),type,amount:+v.amount,date:v.date,category:v.category,description:v.description,person:v.person,status:v.status||'received',paidBy:v.paidBy,recurring:v.frequency==='Recurring',createdBy:state.user,createdAt:new Date().toISOString()});state.tab=type;activity(`${state.user} added ${type==='expense'?'an expense':'income'} of ${money(v.amount)} for ${v.description}.`)})}
function openDebt(){openSheet('Record debt',formWrap(`${field('Original amount','amount','number','','step="0.01" required')}${selectField('Person','person',options(['Joey','Ama']))}${selectField('Type','direction',options(['borrowed','lent']))}${field('Due date','due','date',today)}${field('What is it for?','description','text','','required','full')}`));setupForm(v=>{data.debts.push({...v,id:uid('d'),amount:+v.amount,date:today,createdBy:state.user});activity(`${state.user} recorded ${money(v.amount)} ${v.direction} by ${v.person}.`)})}
function openRepayment(id){const d=data.debts.find(x=>x.id===id);if(!d)return;openSheet('Record repayment',formWrap(`${field('Amount','amount','number','','step="0.01" required')}${field('Date','date','date',today,'required')}${selectField('Paid by','person',options(['Joey','Ama']))}<div class="field full"><small>For ${d.person}'s ${money(d.amount)} debt</small></div>`));setupForm(v=>{data.debtPayments.push({id:uid('dp'),debtId:id,amount:+v.amount,date:v.date,person:v.person});activity(`${v.person} recorded a ${money(v.amount)} repayment.`)})}
function openGoal(){openSheet('New savings goal',formWrap(`${field('Goal name','name','text','','required','full')}${field('Target','target','number','','required')}${field('Already saved','current','number','0')}${field('Target date','date','date',today)}`));setupForm(v=>data.goals.push({...v,id:uid('g'),target:+v.target,current:+v.current}))}
function openContribution(id){const g=data.goals.find(x=>x.id===id);openSheet(`Save toward ${g.name}`,formWrap(`${field('Contribution','amount','number','','step="0.01" required autofocus','full')}`,'Add to goal'));setupForm(v=>{g.current=Math.min(g.target,g.current+(+v.amount));activity(`${state.user} added ${money(v.amount)} to ${g.name}.`)})}
function openCustomer(){openSheet('New customer',formWrap(`${field('Name','name','text','','required')}${field('Company','company')}${field('Email','email','email','','','full')}${field('Phone / WhatsApp','phone','tel','','','full')}`));setupForm(v=>data.customers.push({...v,id:uid('c')}))}
function openProject(){if(!data.customers.length)return toast('Add a customer first');openSheet('New project',formWrap(`${field('Project name','name','text','','required','full')}${selectField('Customer','customerId',options(data.customers,c=>c.id,c=>c.name),'full')}${field('Agreed amount','amount','number','','required')}${field('Amount paid','paid','number','0')}${selectField('Status','status',options(['Inquiry','Quoted','Active','Awaiting Payment','Completed','Cancelled']))}${field('Due date','due','date',today)}`));setupForm(v=>data.projects.push({...v,id:uid('p'),amount:+v.amount,paid:+v.paid}))}
function openWork(){if(!data.customers.length)return toast('Add a customer first');openSheet('Log completed work',formWrap(`${selectField('Customer','customerId',options(data.customers,c=>c.id,c=>c.name),'full')}${field('Work completed','description','text','','required','full')}${field('Billable amount','amount','number','','required')}${field('Date','date','date',today)}`));setupForm(v=>data.work.push({...v,id:uid('w'),amount:+v.amount}))}
function openNewInvoice(){if(!data.customers.length)return toast('Add a customer first');const num=`INV-${new Date().getFullYear()}-${String(data.invoices.length+1).padStart(4,'0')}`;openSheet('Create invoice',formWrap(`${field('Invoice number','number','text',num,'readonly')}${selectField('Customer','customerId',options(data.customers,c=>c.id,c=>c.name))}${field('Description','description','text','','required','full')}${field('Amount','amount','number','','required')}${field('Due date','due','date',iso(new Date(Date.now()+14*864e5)),'required')}`,'Create invoice'));setupForm(v=>data.invoices.push({id:uid('i'),number:v.number,customerId:v.customerId,issue:today,due:v.due,status:'Draft',items:[{description:v.description,qty:1,rate:+v.amount}],discount:0,tax:0}))}
function openInvoice(id){const i=data.invoices.find(x=>x.id===id);const total=invoiceTotal(i),bal=invoiceBalance(i);openSheet(i.number,`<div class="invoice-paper"><div class="invoice-brand"><div><h2>OURS.</h2><small>Creative services</small></div><div class="invoice-meta"><b>INVOICE</b><br>${i.number}<br>Issued ${prettyDate(i.issue)}</div></div><div class="invoice-to"><small>BILLED TO</small><br><b>${customer(i.customerId).name}</b><br><span>${customer(i.customerId).email||''}</span></div><table class="invoice-items"><thead><tr><th>Description</th><th>Amount</th></tr></thead><tbody>${i.items.map(x=>`<tr><td>${x.description}<br><small>${x.qty} × ${money(x.rate)}</small></td><td>${money(x.qty*x.rate)}</td></tr>`).join('')}</tbody></table><div class="invoice-total"><small>BALANCE DUE</small><br><b>${money(bal)}</b><p>Total ${money(total)} · Paid ${money(invoicePaid(i))}</p></div></div><div class="form-actions invoice-actions"><button class="secondary" id="print">Print / PDF</button>${bal?'<button class="primary" id="pay-invoice">Record payment</button>':''}</div>`);$('#print').onclick=()=>window.print();$('#pay-invoice')?.addEventListener('click',()=>openInvoicePayment(id))}
function openInvoicePayment(id){const i=data.invoices.find(x=>x.id===id);openSheet('Record invoice payment',formWrap(`${field('Amount','amount','number',invoiceBalance(i),'step="0.01" min="0.01" required')}${field('Date','date','date',today)}${selectField('Method','method',options(['Mobile Money','Bank transfer','Cash','Card']))}${field('Reference','reference')}`));setupForm(v=>{data.invoicePayments.push({...v,id:uid('ip'),invoiceId:id,amount:+v.amount});i.status=invoiceBalance(i)<=0?'Paid':'Partially Paid';activity(`${customer(i.customerId).name} paid ${money(v.amount)} against ${i.number}.`)})}
function openReview(){const t=totals();openSheet(`${monthName} review`,`<section class="hero"><span class="eyebrow">MONTH-END POSITION</span><div class="hero-number">${shortMoney(t.remaining)}</div></section><div class="snapshot"><div class="snap"><b>${shortMoney(t.income)}</b><span>Income</span></div><div class="snap"><b>${shortMoney(t.expense)}</b><span>Expenses</span></div><div class="snap"><b>${shortMoney(data.debtPayments.reduce((s,p)=>s+p.amount,0))}</b><span>Debt repaid</span></div><div class="snap"><b>${shortMoney(t.receivable)}</b><span>Outstanding</span></div></div><section class="section"><div class="section-title"><h2>Our month, simply</h2></div><p style="color:var(--muted);line-height:1.6">Together, you brought in ${money(t.income)} and spent ${money(t.expense)}. Your current position is ${money(t.remaining)}, with ${money(t.debt)} in personal debt and ${money(t.receivable)} still due from customers.</p></section>`)}
function openSearch(){openSheet('Search everything',`<input id="search" class="search-input" placeholder="Transactions, customers, invoices…" autofocus><ul id="results" class="clean-list"></ul>`);const inp=$('#search');const go=()=>{const q=inp.value.toLowerCase().trim();const out=[];if(q){data.transactions.filter(x=>`${x.description} ${x.category} ${x.person}`.toLowerCase().includes(q)).forEach(x=>out.push(row(x.description,`${x.category} · transaction`,money(x.amount))));data.customers.filter(x=>`${x.name} ${x.company}`.toLowerCase().includes(q)).forEach(x=>out.push(row(x.name,'Customer',x.email||'')));data.invoices.filter(x=>`${x.number} ${customer(x.customerId).name}`.toLowerCase().includes(q)).forEach(x=>out.push(row(x.number,customer(x.customerId).name,money(invoiceBalance(x)))))}$('#results').innerHTML=out.join('')||(q?'<div class="empty">No matching records</div>':'')};inp.oninput=go;setTimeout(()=>inp.focus(),100)}

/* Customer-led invoicing */
function businessView(){const outstanding=data.invoices.reduce((s,i)=>s+(i.status==='Paid'?0:invoiceTotal(i)),0);return `${pageHead('Business','FREELANCE WORKSPACE','<button class="text-button" data-action="add-customer">New customer</button>')}<section class="hero"><span class="eyebrow">OUTSTANDING INVOICES</span><div class="hero-number">${shortMoney(outstanding)}</div><div class="metric-row"><div class="metric"><b>${data.customers.length}</b><span>Customers</span></div><div class="metric"><b>${data.projects.filter(p=>p.status==='Active').length}</b><span>Active work</span></div><div class="metric"><b>${data.invoices.filter(i=>i.status!=='Paid').length}</b><span>Open invoices</span></div></div></section><section class="section"><div class="section-title"><h2>Customers</h2><button class="text-button" data-action="add-project">Add project</button></div><ul class="clean-list">${data.customers.map(c=>{const inv=data.invoices.filter(i=>i.customerId===c.id);const due=inv.filter(i=>i.status!=='Paid').reduce((s,i)=>s+invoiceTotal(i),0);return `<li class="list-row tappable" data-customer="${c.id}"><span class="row-icon">C</span><span class="row-main"><b>${c.name}</b><span>${inv.length} invoice${inv.length===1?'':'s'} · ${c.email||'No email'}</span></span><span class="row-side"><b>${money(due)}</b><span>outstanding</span></span></li>`}).join('')}</ul></section><section class="section"><div class="section-title"><h2>Recent work</h2><button class="text-button" data-action="add-work">Log work</button></div><ul class="clean-list">${data.work.slice().reverse().map(w=>row(w.description,`${customer(w.customerId).name} · ${prettyDate(w.date)}`,money(w.amount),'amount-in','W')).join('')}</ul></section><section class="section"><div class="section-title"><h2>Invoices</h2><button class="text-button" data-action="add-invoice">Create invoice</button></div><ul class="clean-list">${data.invoices.slice().reverse().map(i=>`<li class="list-row tappable" data-invoice="${i.id}"><span class="row-icon">I</span><span class="row-main"><b>${i.number}</b><span>${customer(i.customerId).name} · ${prettyDate(i.issue)}</span></span><span class="row-side"><b>${money(invoiceTotal(i))}</b><span class="status ${i.status==='Paid'?'':'warn'}">${i.status}</span></span></li>`).join('')}</ul></section>`}

function openCustomerProfile(id){const c=customer(id),invoices=data.invoices.filter(i=>i.customerId===id).sort((a,b)=>b.issue.localeCompare(a.issue));const total=invoices.reduce((s,i)=>s+invoiceTotal(i),0),paid=invoices.filter(i=>i.status==='Paid').reduce((s,i)=>s+invoiceTotal(i),0);openSheet(c.name,`<div class="customer-heading"><div class="customer-monogram">${c.name[0]}</div><div><b>${c.company||c.name}</b><span>${c.email||''}${c.phone?` · ${c.phone}`:''}</span></div></div><div class="snapshot"><div class="snap"><b>${money(total)}</b><span>Total invoiced</span></div><div class="snap"><b>${money(total-paid)}</b><span>Outstanding</span></div></div><section class="section"><div class="section-title"><h2>Invoice history</h2><button class="text-button" id="customer-new-invoice">New invoice</button></div><ul class="clean-list">${invoices.length?invoices.map(i=>`<li class="list-row tappable" data-profile-invoice="${i.id}"><span class="row-icon">I</span><span class="row-main"><b>${i.number}</b><span>${prettyDate(i.issue)} · ${i.items.length} item${i.items.length===1?'':'s'}</span></span><span class="row-side"><b>${money(invoiceTotal(i))}</b><span class="status ${i.status==='Paid'?'':'warn'}">${i.status}</span></span></li>`).join(''):'<div class="empty"><b>No invoices yet</b>Create the first invoice for this customer.</div>'}</ul></section>`);$('#customer-new-invoice').onclick=()=>openInvoiceBuilder(null,id);$$('[data-profile-invoice]').forEach(x=>x.onclick=()=>openInvoice(x.dataset.profileInvoice))}

function invoiceItemRow(item={description:'',qty:1,rate:0}){return `<div class="invoice-edit-row"><div class="field item-description"><label>Product / description</label><input class="item-desc" value="${escapeHtml(item.description)}" placeholder="e.g. Social media flier" required></div><div class="field"><label>Qty</label><input class="item-qty" type="number" min="0.01" step="0.01" value="${item.qty}" required></div><div class="field"><label>Unit price</label><input class="item-rate" type="number" min="0" step="0.01" value="${item.rate}" required></div><div class="item-total"><small>Line total</small><b>${money(item.qty*item.rate)}</b></div><button type="button" class="remove-item" aria-label="Remove product">×</button></div>`}
function escapeHtml(s=''){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function openInvoiceBuilder(invoiceId=null,presetCustomer=''){const editing=invoiceId?data.invoices.find(i=>i.id===invoiceId):null;const number=editing?.number||`INV-${new Date().getFullYear()}-${String(data.invoices.length+1).padStart(4,'0')}`;const items=editing?.items?.length?editing.items:[{description:'',qty:1,rate:0}];openSheet(editing?'Edit draft invoice':'Create invoice',`<form id="invoice-builder" class="invoice-builder"><div class="field"><label>Customer</label><div class="customer-select-row"><select id="invoice-customer" required><option value="">Select customer</option>${options(data.customers,c=>c.id,c=>c.name)}</select><button type="button" class="secondary" id="inline-customer">+ New</button></div></div><div id="inline-customer-fields" class="inline-customer hidden"><div class="field"><label>Customer name</label><input id="new-customer-name" placeholder="Customer name"></div><div class="field"><label>Email</label><input id="new-customer-email" type="email" placeholder="Email address"></div></div><div class="invoice-details"><div class="field"><label>Invoice number</label><input value="${number}" readonly></div><div class="field"><label>Invoice date</label><input id="invoice-date" type="date" value="${editing?.issue||today}" required></div><div class="field"><label>Due date</label><input id="invoice-due" type="date" value="${editing?.due||iso(new Date(Date.now()+14*864e5))}" required></div></div><div class="invoice-items-head"><div><span class="eyebrow">INVOICE ITEMS / PRODUCTS</span><h3>What are you billing for?</h3></div><button type="button" class="text-button" id="add-product">+ Add product</button></div><div id="invoice-edit-items">${items.map(invoiceItemRow).join('')}</div><div class="builder-totals"><span>Subtotal</span><b id="builder-subtotal">${money(invoiceTotal(editing||{items}))}</b><span>Total</span><strong id="builder-total">${money(invoiceTotal(editing||{items}))}</strong></div><div class="builder-actions"><button type="button" class="secondary close-form">Cancel</button><button type="submit" class="primary">Save Draft</button></div></form>`);const customerSelect=$('#invoice-customer');customerSelect.value=editing?.customerId||presetCustomer||'';$('#inline-customer').onclick=()=>$('#inline-customer-fields').classList.toggle('hidden');$('#add-product').onclick=()=>{$('#invoice-edit-items').insertAdjacentHTML('beforeend',invoiceItemRow());bindInvoiceItems();recalcInvoice()};$('.close-form').onclick=closeSheet;function bindInvoiceItems(){$$('.invoice-edit-row').forEach(r=>{r.querySelectorAll('input').forEach(i=>i.oninput=recalcInvoice);r.querySelector('.remove-item').onclick=()=>{if($$('.invoice-edit-row').length===1)return toast('An invoice needs at least one product');r.remove();recalcInvoice()}})}function recalcInvoice(){let total=0;$$('.invoice-edit-row').forEach(r=>{const value=(+r.querySelector('.item-qty').value||0)*(+r.querySelector('.item-rate').value||0);r.querySelector('.item-total b').textContent=money(value);total+=value});$('#builder-subtotal').textContent=money(total);$('#builder-total').textContent=money(total)}bindInvoiceItems();$('#invoice-builder').onsubmit=e=>{e.preventDefault();let customerId=customerSelect.value;const newName=$('#new-customer-name').value.trim();if(!customerId&&newName){const c={id:uid('c'),name:newName,company:newName,email:$('#new-customer-email').value.trim(),phone:''};data.customers.push(c);customerId=c.id}if(!customerId)return toast('Choose or create a customer');const invoiceItems=$$('.invoice-edit-row').map(r=>({description:r.querySelector('.item-desc').value.trim(),qty:+r.querySelector('.item-qty').value,rate:+r.querySelector('.item-rate').value}));if(invoiceItems.some(x=>!x.description||x.qty<=0))return toast('Complete every invoice item');if(editing){editing.customerId=customerId;editing.issue=$('#invoice-date').value;editing.due=$('#invoice-due').value;editing.items=invoiceItems;editing.status='Draft'}else data.invoices.push({id:uid('i'),number,customerId,issue:$('#invoice-date').value,due:$('#invoice-due').value,status:'Draft',items:invoiceItems,discount:0,tax:0});activity(`${state.user} saved ${number} as a draft.`);save();closeSheet();render();toast('Invoice draft saved')}}

function openNewInvoice(){openInvoiceBuilder()}
function setInvoiceStatus(i,status){if(status==='Paid'){const remaining=invoiceBalance(i);if(remaining>0)data.invoicePayments.push({id:uid('ip'),invoiceId:i.id,amount:remaining,date:today,method:'Marked paid',reference:''})}else if(status==='Unpaid'){data.invoicePayments=data.invoicePayments.filter(p=>p.invoiceId!==i.id)}i.status=status;activity(`${state.user} marked ${i.number} as ${status.toLowerCase()}.`);save();openInvoice(i.id);render()}
function openInvoice(id){const i=data.invoices.find(x=>x.id===id);if(!i)return;const total=invoiceTotal(i),paid=i.status==='Paid'?total:invoicePaid(i),bal=i.status==='Paid'?0:Math.max(0,total-paid);openSheet(i.number,`<div class="invoice-paper" id="printable-invoice"><div class="invoice-brand"><div><h2>OURS.</h2><small>Creative services · Accra, Ghana</small></div><div class="invoice-meta"><b>INVOICE</b><br>${i.number}<br>${prettyDate(i.issue)}</div></div><div class="invoice-bill-grid"><div class="invoice-to"><small>BILLED TO</small><br><b>${customer(i.customerId).name}</b><br><span>${customer(i.customerId).company||''}</span><br><span>${customer(i.customerId).email||''}</span></div><div class="invoice-to right"><small>PAYMENT STATUS</small><br><b>${i.status}</b><br><span>Due ${prettyDate(i.due)}</span></div></div><table class="invoice-items"><thead><tr><th>Description</th><th>Qty</th><th>Unit price</th><th>Total</th></tr></thead><tbody>${i.items.map(x=>`<tr><td>${escapeHtml(x.description)}</td><td>${x.qty}</td><td>${money(x.rate)}</td><td>${money(x.qty*x.rate)}</td></tr>`).join('')}</tbody></table><div class="invoice-summary"><div><span>Subtotal</span><b>${money(total)}</b></div><div class="grand-total"><span>Total</span><b>${money(total)}</b></div><div><span>Balance due</span><b>${money(bal)}</b></div></div><div class="invoice-footer">Thank you for your business.</div></div><div class="invoice-action-stack">${i.status==='Draft'?`<button class="secondary" id="edit-invoice">Edit Draft</button>`:''}<button class="secondary" id="mark-unpaid">Mark as Unpaid</button><button class="primary" id="mark-paid">Mark as Paid</button><button class="download-button" id="download-invoice">↓ Download Invoice</button></div>`);$('#edit-invoice')?.addEventListener('click',()=>openInvoiceBuilder(id));$('#mark-paid').onclick=()=>setInvoiceStatus(i,'Paid');$('#mark-unpaid').onclick=()=>setInvoiceStatus(i,'Unpaid');$('#download-invoice').onclick=()=>downloadInvoice(i)}
function downloadInvoice(i){
  const c=customer(i.customerId), total=invoiceTotal(i), esc=s=>String(s??'').replace(/[^\x20-\x7E]/g,' ').replace(/([\\()])/g,'\\$1');
  const cmd=[]; const text=(x,y,size,value,bold=false,color='0.145 0.161 0.263')=>cmd.push(`${color} rg BT /F${bold?2:1} ${size} Tf ${x} ${y} Td (${esc(value)}) Tj ET`);
  cmd.push('0.227 0.306 0.984 rg 0 760 612 32 re f');
  text(44,724,25,'OURS.',true,'0.227 0.306 0.984'); text(44,704,9,'CREATIVE SERVICES  /  ACCRA, GHANA');
  text(568,724,19,'INVOICE',true); text(568,706,10,i.number,false,'0.435 0.451 0.533');
  text(44,655,8,'BILLED TO',true,'0.227 0.306 0.984'); text(44,635,14,c.name,true); text(44,618,9,c.company||''); text(44,603,9,c.email||''); text(44,588,9,c.phone||'');
  text(410,655,8,'INVOICE DETAILS',true,'0.227 0.306 0.984'); text(410,635,9,`Date: ${i.issue}`); text(410,618,9,`Due: ${i.due}`); text(410,601,9,`Status: ${i.status}`,true);
  cmd.push('0.871 0.878 0.929 RG 44 566 m 568 566 l S');
  text(44,545,8,'DESCRIPTION',true); text(365,545,8,'QTY',true); text(422,545,8,'UNIT PRICE',true); text(525,545,8,'TOTAL',true);
  let y=520; i.items.slice(0,18).forEach(item=>{text(44,y,9,item.description.slice(0,48));text(380,y,9,item.qty);text(432,y,9,money(item.rate));text(520,y,9,money(item.qty*item.rate),true);cmd.push(`0.92 0.925 0.95 RG 44 ${y-11} m 568 ${y-11} l S`);y-=30});
  y=Math.max(105,y-8); text(410,y,9,'SUBTOTAL');text(510,y,10,money(total),true);y-=27;cmd.push(`0.227 0.306 0.984 RG 410 ${y+15} m 568 ${y+15} l S`);text(410,y,12,'TOTAL',true);text(500,y,14,money(total),true,'0.227 0.306 0.984');y-=25;text(410,y,9,'PAYMENT STATUS');text(510,y,9,i.status,true);
  text(44,58,9,'Thank you for your business.'); text(44,40,8,'This invoice was generated by Ours.',false,'0.435 0.451 0.533');
  const stream=cmd.join('\n'), objects=[null,'<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>',`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 5 0 R /F2 6 0 R >> >> /Contents 4 0 R >>`,`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`,'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>'];
  let pdf='%PDF-1.4\n', offsets=[0];for(let n=1;n<objects.length;n++){offsets[n]=pdf.length;pdf+=`${n} 0 obj\n${objects[n]}\nendobj\n`}const xref=pdf.length;pdf+=`xref\n0 ${objects.length}\n0000000000 65535 f \n`;for(let n=1;n<objects.length;n++)pdf+=`${String(offsets[n]).padStart(10,'0')} 00000 n \n`;pdf+=`trailer\n<< /Size ${objects.length} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;
  const blob=new Blob([pdf],{type:'application/pdf'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${i.number}-${c.name.replace(/[^a-z0-9]+/gi,'-')}.pdf`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('PDF invoice downloaded');
}

/* Remaining V1 finance, planning, agenda, project and report workflows */
function ensureData(){
  if(!data || typeof data!=='object') data=structuredClone(emptyData);
  Object.keys(emptyData).forEach(key=>{if(!Array.isArray(data[key]))data[key]=[]});
}
function mergeWorkspaceData(local={},remote={},preference='local'){
  const merged=structuredClone(emptyData);
  Object.keys(emptyData).forEach(key=>{
    const localValues=Array.isArray(local[key])?local[key]:[],remoteValues=Array.isArray(remote[key])?remote[key]:[];
    const values=preference==='remote'?[...localValues,...remoteValues]:[...remoteValues,...localValues];
    const records=new Map();
    values.forEach(item=>{
      let identity;
      if(key==='transactions'&&item&&typeof item==='object')identity=item.id||JSON.stringify(item);
      else identity=typeof item==='object'&&item!==null?(item.id||item.month||JSON.stringify(item)):String(item);
      const existing=records.get(identity);
      const itemIsRecovered=String(item?.id||'').startsWith('recovered-grace-');
      const existingIsRecovered=String(existing?.id||'').startsWith('recovered-grace-');
      if(!existing||!itemIsRecovered||existingIsRecovered)records.set(identity,item);
    });
    merged[key]=[...records.values()];
  });
  const genuineTransactionKeys=new Set(merged.transactions
    .filter(item=>!String(item.id||'').startsWith('recovered-grace-'))
    .map(item=>`${item.date}|${item.type}|${Number(item.amount)||0}|${item.person}|${item.category}`));
  merged.transactions=merged.transactions.filter(item=>{
    if(!String(item.id||'').startsWith('recovered-grace-'))return true;
    const key=`${item.date}|${item.type}|${Number(item.amount)||0}|${item.person}|${item.category}`;
    return !genuineTransactionKeys.has(key);
  });
  const deleted=new Set(merged.deletedCustomerIds);
  merged.customers=merged.customers.filter(item=>!deleted.has(item.id));
  merged.projects=merged.projects.filter(item=>!deleted.has(item.customerId));
  merged.work=merged.work.filter(item=>!deleted.has(item.customerId));
  const removedInvoices=new Set(merged.invoices.filter(item=>deleted.has(item.customerId)).map(item=>item.id));
  merged.invoices=merged.invoices.filter(item=>!deleted.has(item.customerId));
  merged.invoicePayments=merged.invoicePayments.filter(item=>!removedInvoices.has(item.invoiceId));
  return merged;
}
window.mergeWorkspaceData=mergeWorkspaceData;
function hasLocalRecordsMissingRemotely(local={},remote={}){return Object.keys(emptyData).some(key=>{const remoteIds=new Set((Array.isArray(remote[key])?remote[key]:[]).map(item=>typeof item==='object'&&item!==null?(item.id||item.month||JSON.stringify(item)):String(item)));return (Array.isArray(local[key])?local[key]:[]).some(item=>!remoteIds.has(typeof item==='object'&&item!==null?(item.id||item.month||JSON.stringify(item)):String(item)))})}

let cloudRefreshTimer;
async function refreshCloudData(){
  if(!window.cloudReady||!localStorage.getItem('ours-access-token')||document.hidden)return;
  try{const remote=await loadCloudWorkspace(state.user);if(!remote)return;const needsUpload=hasLocalRecordsMissingRemotely(data,remote),merged=mergeWorkspaceData(data,remote,'remote');if(JSON.stringify(merged)!==JSON.stringify(data)){data=merged;localStorage.setItem('ours-data-v2',JSON.stringify(data));render()}if(needsUpload)await persistCloudWorkspace(merged)}catch(error){console.warn('Cloud refresh delayed',error.message)}
}
function startCloudRefresh(){clearInterval(cloudRefreshTimer);refreshCloudData();cloudRefreshTimer=setInterval(refreshCloudData,10000)}
async function manualSync(){
  const button=$('#sync-btn');if(!window.cloudReady||!localStorage.getItem('ours-access-token'))return toast('Log in to sync your ledger');
  button?.classList.add('syncing');button&&(button.disabled=true);
  try{const localSnapshot=structuredClone(data),remote=await loadCloudWorkspace(state.user),merged=mergeWorkspaceData(localSnapshot,remote||{},'local');await persistCloudWorkspace(merged);data=merged;localStorage.setItem('ours-data-v2',JSON.stringify(data));render();toast('Ledger synced successfully')}
  catch(error){toast(`Sync failed: ${error.message}`)}finally{button?.classList.remove('syncing');if(button)button.disabled=false}
}
function logout(){clearInterval(cloudRefreshTimer);localStorage.removeItem('ours-user');localStorage.removeItem('ours-access-token');localStorage.removeItem('ours-refresh-token');location.reload()}

function handleAction(a){const map={'add-income':()=>openTransaction('income'),'add-expense':()=>openTransaction('expense'),'add-shared':openSharedExpense,'add-recurring':openRecurring,'add-debt':openDebt,'add-repayment':()=>data.debts.length?openRepayment(data.debts[0].id):toast('Add a debt first'),'add-goal':openGoal,'edit-plan':openPlanEditor,'add-customer':openCustomer,'add-project':openProject,'add-work':openWork,'add-invoice':openNewInvoice,review:openReview,agenda:openAgenda};(map[a]||(()=>{}))()}

