function planView(){const plan=data.plans.find(p=>p.month===monthKey)||{month:monthKey,income:0,expenses:0,savings:0,debt:0};const projected=plan.income-plan.expenses-plan.savings-plan.debt;return `${pageHead('Plan ahead','MONTHLY PLANNING','<button class="text-button" data-action="edit-plan">Edit plan</button>')}<section class="hero"><span class="eyebrow">PROJECTED REMAINING</span><div class="hero-number">${shortMoney(projected)}</div><div class="hero-sub">after expenses, saving and debt payments</div></section><section class="section"><div class="section-title"><h2>Planned vs actual</h2><span>${monthName}</span></div>${compareRow('Income',plan.income,totals().income)}${compareRow('Expenses',plan.expenses,totals().expense)}${compareRow('Savings',plan.savings,0)}${compareRow('Debt repayment',plan.debt,data.debtPayments.filter(p=>p.date.startsWith(monthKey)).reduce((s,p)=>s+p.amount,0))}</section><section class="section"><div class="section-title"><h2>Financial agenda</h2><button class="text-button" data-action="agenda">View all</button></div><ul class="clean-list">${agendaItems().slice(0,4).map(a=>row(a.name,`${a.kind} · ${prettyDate(a.date)}`,money(a.amount),a.direction==='in'?'amount-in':'amount-out',a.icon)).join('')}</ul></section><section class="section"><div class="section-title"><h2>Savings goals</h2><button class="text-button" data-action="add-goal">New goal</button></div>${data.goals.map(goalRow).join('')}</section>`}
function openPlanEditor(){const p=data.plans.find(x=>x.month===monthKey)||{month:monthKey,income:0,expenses:0,savings:0,debt:0};openSheet(`Plan ${monthName}`,formWrap(`${field('Expected income','income','number',p.income,'min="0" step="0.01"')}${field('Planned expenses','expenses','number',p.expenses,'min="0" step="0.01"')}${field('Savings target','savings','number',p.savings,'min="0" step="0.01"')}${field('Debt repayments','debt','number',p.debt,'min="0" step="0.01"')}`,'Update plan'));setupForm(v=>{Object.assign(p,{income:+v.income,expenses:+v.expenses,savings:+v.savings,debt:+v.debt});if(!data.plans.includes(p))data.plans.push(p)})}
function agendaItems(){return [...data.transactions.filter(t=>t.status==='expected').map(t=>({name:t.description,kind:'Expected income',date:t.date,amount:t.amount,direction:'in',icon:'↙'})),...data.recurring.filter(r=>r.active).map(r=>({name:r.name,kind:'Recurring payment',date:r.next,amount:r.amount,direction:'out',icon:'↻'})),...data.invoices.filter(i=>i.status!=='Paid').map(i=>({name:`${i.number} · ${customer(i.customerId).name}`,kind:'Invoice due',date:i.due,amount:invoiceTotal(i),direction:'in',icon:'I'})),...data.debts.filter(d=>d.due).map(d=>({name:`${d.person} debt`,kind:'Debt payment',date:d.due,amount:d.amount-data.debtPayments.filter(p=>p.debtId===d.id).reduce((s,p)=>s+p.amount,0),direction:'out',icon:'D'}))].filter(x=>x.amount>0).sort((a,b)=>a.date.localeCompare(b.date))}
function openAgenda(){const items=agendaItems();openSheet('Financial agenda',`<div class="agenda-date">UPCOMING COMMITMENTS</div><ul class="clean-list">${items.map(a=>row(a.name,`${a.kind} · ${prettyDate(a.date)}`,money(a.amount),a.direction==='in'?'amount-in':'amount-out',a.icon)).join('')||'<div class="empty">Nothing upcoming.</div>'}</ul>`)}

