function moreView(){const tx=reportData(),income=tx.filter(t=>t.type==='income'&&t.status!=='expected').reduce((s,t)=>s+t.amount,0),expense=tx.filter(t=>t.type==='expense').reduce((s,t)=>s+t.amount,0),cats=[...new Set(data.transactions.map(t=>t.category))];return `${pageHead('Reports','FILTERED FINANCIAL VIEW')}<div class="report-filters"><select id="report-person"><option>All</option><option>Joey</option><option>Ama</option><option>Both</option></select><select id="report-category"><option>All</option>${cats.map(c=>`<option>${c}</option>`).join('')}</select></div><section class="hero"><span class="eyebrow">NET MONTHLY POSITION</span><div class="hero-number">${shortMoney(income-expense)}</div><div class="metric-row"><div class="metric"><b>${shortMoney(income)}</b><span>Income</span></div><div class="metric"><b>${shortMoney(expense)}</b><span>Expenses</span></div><div class="metric"><b>${tx.length}</b><span>Records</span></div></div></section><section class="section"><div class="section-title"><h2>Category breakdown</h2><span>${monthName}</span></div>${categoryBreakdown(tx)}</section><section class="section"><div class="section-title"><h2>Business receivables</h2></div><ul class="clean-list">${data.invoices.filter(i=>i.status!=='Paid').map(i=>row(i.number,customer(i.customerId).name,money(invoiceTotal(i)),'amount-in','I')).join('')||'<div class="empty">All invoices are paid.</div>'}</ul></section><section class="section"><div class="section-title"><h2>Activity</h2></div><ul class="clean-list">${data.activities.slice(0,8).map(a=>row(a.text,prettyDate(a.date),'','','•')).join('')}</ul></section><section class="section"><button class="secondary" id="export">Export my data</button> <button class="text-button" data-action="review">Monthly review</button></section>`}
function categoryBreakdown(tx){const expenses=tx.filter(t=>t.type==='expense'),total=expenses.reduce((s,t)=>s+t.amount,0),groups={};expenses.forEach(t=>groups[t.category]=(groups[t.category]||0)+t.amount);return Object.entries(groups).sort((a,b)=>b[1]-a[1]).map(([name,value])=>`<div class="goal-row"><div class="goal-top"><b>${name}</b><span>${money(value)}</span></div><div class="progress"><i style="width:${total?value/total*100:0}%"></i></div><div class="goal-values"><span>${total?Math.round(value/total*100):0}% of spending</span></div></div>`).join('')||'<div class="empty">No expenses match these filters.</div>'}

